(4, 0, '2026-08-23 18:05:45', '2026-08-23 18:05:45', '<!-- wp:page-list /-->', 'Navigation', '', 'publish', 'closed', 'closed', '', 'navigation', '', '', '2026-08-23 18:05:45', '2026-08-23 18:05:45', '', 0, 'https://academiatraining.eu/2026/08/23/navigation/', 0, 'wp_navigation', '', 0),
(8, 1, '2026-08-23 18:09:14', '2026-08-23 18:09:14', 'Academia runs public classroom training in Amsterdam throughout the year, covering business and management, finance, technology, supply chain, HR and compliance. The venue sits in the Zuidas business district, within easy reach of the central station and the airport, and is also available for private in-company sessions for teams based in Netherlands.', 'Amsterdam', 'Public classroom courses and in-company training in Amsterdam, in the Zuidas business district. Small groups, full equipment, lunch included.', 'publish', 'closed', 'closed', '', 'amsterdam', '', '', '2026-08-23 18:09:14', '2026-08-23 18:09:14', '', 0, 'https://academiatraining.eu/locations/amsterdam/', 0, 'location', '', 0),
(9, 1, '2026-08-23 18:09:14', '2026-08-23 18:09:14', 'Academia runs public classroom training in Rotterdam throughout the year, covering business and management, finance, technology, supply chain, HR and compliance. The venue sits in the Kop van Zuid, within easy reach of the central station and the airport, and is also available for private in-company sessions for teams based in Netherlands.', 'Rotterdam', 'Public classroom courses and in-company training in Rotterdam, in the Kop van Zuid. Small groups, full equipment, lunch included.', 'publish', 'closed', 'closed', '', 'rotterdam', '', '', '2026-08-23 18:09:14', '2026-08-23 18:09:14', '', 0, 'https://academiatraining.eu/locations/rotterdam/', 0, 'location', '', 0),
