(2159, 1, '2026-08-23 22:58:07', '2026-08-23 22:58:07', '<!-- wp:group {\"className\":\"section\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group section\">\n	<!-- wp:academia/breadcrumbs /-->\n	<!-- wp:columns -->\n	<div class=\"wp-block-columns\">\n		<!-- wp:column {\"width\":\"58%\"} -->\n		<div class=\"wp-block-column\" style=\"flex-basis:58%\">\n			<!-- wp:heading {\"level\":1} --><h1 class=\"wp-block-heading\">Talk to a training advisor</h1><!-- /wp:heading -->\n			<!-- wp:paragraph {\"className\":\"is-style-academia-lede\"} --><p class=\"is-style-academia-lede\">Not sure which course fits, or need something that is not in the catalogue? Tell us the situation and we will point you at the right option — including telling you when it is not us.</p><!-- /wp:paragraph -->\n			<!-- wp:academia/lead-form {\"formId\":\"general\",\"showEstimator\":false} /-->\n		</div>\n		<!-- /wp:column -->\n		<!-- wp:column {\"width\":\"42%\"} -->\n		<div class=\"wp-block-column\" style=\"flex-basis:42%\">\n			<!-- wp:html -->\n			<div class=\"card card-pad-lg\">\n				<h4>Direct channels</h4>\n				<div class=\"stack gap-3\" style=\"margin-top:14px\">\n					[academia_contact_channels]\n				</div>\n				<hr style=\"border:none;border-top:1px dashed var(--line);margin:20px 0\">\n				<h4>Response times</h4>\n				<ul class=\"mode-list\" style=\"margin-top:12px\">\n					<li><svg><use href=\"#i-check\"></use></svg> Course enquiries — same working day</li>\n					<li><svg><use href=\"#i-check\"></use></svg> Corporate proposals — 2 working days</li>\n					<li><svg><use href=\"#i-check\"></use></svg> Invoicing and admin — 1 working day</li>\n				</ul>\n				<hr style=\"border:none;border-top:1px dashed var(--line);margin:20px 0\">\n				[academia_office_block]\n				<p class=\"xs muted\" style=\"margin-top:10px\">Courses are delivered at partner venues across Europe — see the locations page for each city.</p>\n			</div>\n			<!-- /wp:html -->\n		</div>\n		<!-- /wp:column -->\n	</div>\n	<!-- /wp:columns -->\n</div>\n<!-- /wp:group -->\n\n\n<!-- wp:group {\"className\":\"section-sm\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group section-sm\">\n	<!-- wp:academia/callback /-->\n</div>\n<!-- /wp:group -->\n\n\n', 'Contact', '', 'inherit', 'closed', 'closed', '', '2139-revision-v1', '', '', '2026-08-23 22:58:07', '2026-08-23 22:58:07', '', 2139, 'https://academiatraining.eu/?p=2159', 0, 'revision', '', 0),
(2160, 1, '2026-08-23 22:58:07', '2026-08-23 22:58:07', '<!-- wp:group {\"className\":\"wrap section\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group wrap section\">\n	<!-- wp:academia/breadcrumbs /-->\n	<!-- wp:paragraph {\"className\":\"is-style-academia-eyebrow\"} --><p class=\"is-style-academia-eyebrow\">Legal</p><!-- /wp:paragraph -->\n	<!-- wp:post-title {\"level\":1} /-->\n	<!-- wp:paragraph {\"fontSize\":\"x-small\",\"className\":\"muted\"} -->\n	[academia_legal_footer]\n	<!-- /wp:paragraph -->\n\n	\n\n	<!-- wp:group {\"style\":{\"spacing\":{\"margin\":{\"top\":\"36px\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"760px\"}} -->\n	<div class=\"wp-block-group\" style=\"margin-top:36px\">\n		<!-- wp:paragraph {\"placeholder\":\"Paste the reviewed legal text here.\"} --><p></p><!-- /wp:paragraph -->\n	</div>\n	<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n\n\n', 'Privacy &amp; GDPR', '', 'inherit', 'closed', 'closed', '', '2144-revision-v1', '', '', '2026-08-23 22:58:07', '2026-08-23 22:58:07', '', 2144, 'https://academiatraining.eu/?p=2160', 0, 'revision', '', 0),
(2161, 1, '2026-08-23 22:58:07', '2026-08-23 22:58:07', '<!-- wp:academia/skills-credits /-->\n\n\n<!-- wp:group {\"backgroundColor\":\"brand-cream\",\"layout\":{\"type\":\"constrained\"},\"align\":\"full\"} -->\n<div class=\"wp-block-group alignfull has-brand-cream-background-color has-background\">\n	<!-- wp:academia/value-comparison /-->\n</div>\n<!-- /wp:group -->\n\n\n<!-- wp:group {\"className\":\"section\",\"backgroundColor\":\"brand-brown\",\"layout\":{\"type\":\"constrained\"},\"align\":\"full\",\"anchor\":\"proposal\"} -->\n<div class=\"wp-block-group alignfull section has-brand-brown-background-color has-background\" id=\"proposal\">\n	<!-- wp:columns -->\n	<div class=\"wp-block-columns\">\n		<!-- wp:column {\"width\":\"40%\"} -->\n		<div class=\"wp-block-column\" style=\"flex-basis:40%\">\n			<!-- wp:paragraph {\"className\":\"is-style-academia-eyebrow\",\"style\":{\"color\":{\"text\":\"#E9C25A\"}}} --><p class=\"is-style-academia-eyebrow has-text-color\" style=\"color:#E9C25A\">Two minutes, no obligation</p><!-- /wp:paragraph -->\n			<!-- wp:heading {\"level\":2,\"style\":{\"color\":{\"text\":\"#ffffff\"}}} --><h2 class=\"wp-block-heading has-text-color\" style=\"color:#ffffff\">Request a corporate training proposal</h2><!-- /wp:heading -->\n			<!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"rgba(242,240,227,.80)\"}}} -->\n			<p class=\"has-text-color\" style=\"color:rgba(242,240,227,.80)\">Tell us roughly what you need. A training advisor reviews every enquiry personally and comes back within two working days with an outline, an expert profile and a price.</p>\n			<!-- /wp:paragraph -->\n			<!-- wp:html -->\n			<div class=\"stack gap-3\" style=\"margin-top:24px;color:rgba(242,240,227,.86);font-size:14px\">\n				<span class=\"center gap-3\"><svg style=\"width:18px;height:18px;color:#6FAC91\"><use href=\"#i-checkc\"></use></svg> Fixed price — no per-participant surprises</span>\n				<span class=\"center gap-3\"><svg style=\"width:18px;height:18px;color:#6FAC91\"><use href=\"#i-checkc\"></use></svg> Your data stays in the EU, GDPR compliant</span>\n				<span class=\"center gap-3\"><svg style=\"width:18px;height:18px;color:#6FAC91\"><use href=\"#i-checkc\"></use></svg> We will say so if we are not the right provider</span>\n				<span class=\"center gap-3\"><svg style=\"width:18px;height:18px;color:#6FAC91\"><use href=\"#i-checkc\"></use></svg> [academia_phone prefix=\"Prefer to talk first? Call \"]</span>\n			</div>\n			<!-- /wp:html -->\n		</div>\n		<!-- /wp:column -->\n		<!-- wp:column {\"width\":\"60%\"} -->\n		<div class=\"wp-block-column\" style=\"flex-basis:60%\">\n			<!-- wp:academia/lead-form {\"formId\":\"corporate\",\"showEstimator\":true} /-->\n		</div>\n		<!-- /wp:column -->\n	</div>\n	<!-- /wp:columns -->\n</div>\n<!-- /wp:group -->\n\n\n', 'Skills Credits', '', 'inherit', 'closed', 'closed', '', '2140-revision-v1', '', '', '2026-08-23 22:58:07', '2026-08-23 22:58:07', '', 2140, 'https://academiatraining.eu/?p=2161', 0, 'revision', '', 0),
(2162, 1, '2026-08-23 22:58:07', '2026-08-23 22:58:07', '<!-- wp:group {\"className\":\"wrap section\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group wrap section\">\n	<!-- wp:academia/breadcrumbs /-->\n	<!-- wp:paragraph {\"className\":\"is-style-academia-eyebrow\"} --><p class=\"is-style-academia-eyebrow\">Legal</p><!-- /wp:paragraph -->\n	<!-- wp:post-title {\"level\":1} /-->\n	<!-- wp:paragraph {\"fontSize\":\"x-small\",\"className\":\"muted\"} -->\n	[academia_legal_footer]\n	<!-- /wp:paragraph -->\n\n	\n\n	<!-- wp:group {\"style\":{\"spacing\":{\"margin\":{\"top\":\"36px\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"760px\"}} -->\n	<div class=\"wp-block-group\" style=\"margin-top:36px\">\n		<!-- wp:paragraph {\"placeholder\":\"Paste the reviewed legal text here.\"} --><p></p><!-- /wp:paragraph -->\n	</div>\n	<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n\n\n', 'Cancellation Policy', '', 'inherit', 'closed', 'closed', '', '2146-revision-v1', '', '', '2026-08-23 22:58:07', '2026-08-23 22:58:07', '', 2146, 'https://academiatraining.eu/?p=2162', 0, 'revision', '', 0),
(2163, 1, '2026-08-23 22:58:07', '2026-08-23 22:58:07', '<!-- wp:group {\"className\":\"section\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group section\">\n	<!-- wp:academia/breadcrumbs /-->\n	<!-- wp:paragraph {\"className\":\"is-style-academia-eyebrow\"} --><p class=\"is-style-academia-eyebrow\">Success stories</p><!-- /wp:paragraph -->\n	<!-- wp:heading {\"level\":1} --><h1 class=\"wp-block-heading\">Where the training actually led</h1><!-- /wp:heading -->\n	<!-- wp:paragraph {\"className\":\"is-style-academia-lede\"} --><p class=\"is-style-academia-lede\">Promotions, career changes, certifications passed and teams that started working differently. These are the outcomes participants and clients told us about six to twelve months later.</p><!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n\n\n<!-- wp:group {\"className\":\"section sec-sand\",\"layout\":{\"type\":\"constrained\"},\"align\":\"full\"} -->\n<div class=\"wp-block-group alignfull section sec-sand\">\n	<!-- wp:heading {\"level\":2,\"className\":\"is-style-academia-underline\"} --><h2 class=\"wp-block-heading is-style-academia-underline\">Career pathways these courses are built for</h2><!-- /wp:heading -->\n	<!-- wp:paragraph {\"className\":\"small muted\"} -->\n	<p class=\"small muted\">Each pathway below is the progression a course sequence is designed to support. Timeframes are planning guidance, not a promise, and we publish no participant names — verified stories will appear here as clients and individuals sign them off.</p>\n	<!-- /wp:paragraph -->\n	<!-- wp:spacer {\"height\":\"32px\"} --><div style=\"height:32px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div><!-- /wp:spacer -->\n	<!-- wp:html -->\n	<div class=\"grid\" style=\"gap:20px\">\n		<div class=\"card card-pad-lg\">\n			<div class=\"between\" style=\"margin-bottom:18px;align-items:flex-start\">\n				<div class=\"center gap-3\">\n					<span class=\"cat-ico\" style=\"background:#2E6B4F;color:#fff\"><svg class=\"ac-icon\" aria-hidden=\"true\"><use href=\"#i-chart\"></use></svg></span>\n					<div><b>Financial analyst → Data analyst</b><div class=\"xs muted\">Finance function, logistics sector · Netherlands</div></div>\n				</div>\n				<span class=\"chip chip-orange\">Data Analytics Foundations + Power BI Advanced</span>\n			</div>\n			<div class=\"beforeafter\">\n				<div class=\"ba-box\"><h6>Starting point</h6><p class=\"small\">Can build a pivot table, but cannot explain a number to the board without three days of preparation.</p></div>\n				<div class=\"ba-arrow\"><svg style=\"width:26px;height:26px\"><use href=\"#i-arrow\"></use></svg></div>\n				<div class=\"ba-box after\"><h6>Target · 6–9 months</h6><p class=\"small\">Owns a commercial dashboard suite; the monthly board pack is automated rather than rebuilt.</p></div>\n			</div>\n		</div>\n		<div class=\"card card-pad-lg\">\n			<div class=\"between\" style=\"margin-bottom:18px;align-items:flex-start\">\n				<div class=\"center gap-3\">\n					<span class=\"cat-ico\" style=\"background:#B14705;color:#fff\"><svg class=\"ac-icon\" aria-hidden=\"true\"><use href=\"#i-brief\"></use></svg></span>\n					<div><b>Project coordinator → Programme manager</b><div class=\"xs muted\">Manufacturing, multi-site · France</div></div>\n				</div>\n				<span class=\"chip chip-orange\">PRINCE2 Practitioner preparation + Stakeholder Management</span>\n			</div>\n			<div class=\"beforeafter\">\n				<div class=\"ba-box\"><h6>Starting point</h6><p class=\"small\">Several years coordinating projects without a formal method, passed over for programme roles for lack of certification.</p></div>\n				<div class=\"ba-arrow\"><svg style=\"width:26px;height:26px\"><use href=\"#i-arrow\"></use></svg></div>\n				<div class=\"ba-box after\"><h6>Target · 4–6 months</h6><p class=\"small\">Certification passed and a programme-level remit — typically a site consolidation or a systems rollout.</p></div>\n			</div>\n		</div>\n		<div class=\"card card-pad-lg\">\n			<div class=\"between\" style=\"margin-bottom:18px;align-items:flex-start\">\n				<div class=\"center gap-3\">\n					<span class=\"cat-ico\" style=\"background:#E0A526;color:#241C15\"><svg class=\"ac-icon\" aria-hidden=\"true\"><use href=\"#i-truck\"></use></svg></span>\n					<div><b>Warehouse supervisor → Supply chain planner</b><div class=\"xs muted\">Distribution, two DCs · Germany</div></div>\n				</div>\n				<span class=\"chip chip-orange\">S&amp;OP + Inventory Optimisation + SAP MM</span>\n			</div>\n			<div class=\"beforeafter\">\n				<div class=\"ba-box\"><h6>Starting point</h6><p class=\"small\">Knows the warehouse floor better than anyone but has never touched planning, and the ERP is a black box.</p></div>\n				<div class=\"ba-arrow\"><svg style=\"width:26px;height:26px\"><use href=\"#i-arrow\"></use></svg></div>\n				<div class=\"ba-box after\"><h6>Target · 9–12 months</h6><p class=\"small\">Runs the demand plan across both distribution centres, with excess stock measurably reduced.</p></div>\n			</div>\n		</div>\n	</div>\n	<p class=\"xs muted\" style=\"margin-top:18px\"><span class=\"sample-flag\">Designed outcomes</span> &nbsp;These describe programme design, not individual participants. No quote on this page was said by anyone.</p>\n	<!-- /wp:html -->\n</div>\n<!-- /wp:group -->\n\n\n<!-- wp:group {\"className\":\"section\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group section\">\n	<!-- wp:heading {\"level\":2,\"className\":\"is-style-academia-underline\"} --><h2 class=\"wp-block-heading is-style-academia-underline\">Client case studies</h2><!-- /wp:heading -->\n	<!-- wp:spacer {\"height\":\"28px\"} --><div style=\"height:28px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div><!-- /wp:spacer -->\n	<!-- wp:query {\"queryId\":7,\"query\":{\"perPage\":6,\"postType\":\"case_study\",\"order\":\"desc\",\"orderBy\":\"date\"},\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-query\">\n		<!-- wp:post-template {\"className\":\"is-style-academia-course-grid\",\"layout\":{\"type\":\"grid\",\"columnCount\":3}} -->\n			<!-- wp:post-featured-image {\"isLink\":true,\"aspectRatio\":\"3/2\"} /-->\n			<!-- wp:post-terms {\"term\":\"sector\",\"fontSize\":\"x-small\"} /-->\n			<!-- wp:post-title {\"isLink\":true,\"level\":3,\"fontSize\":\"x-large\"} /-->\n			<!-- wp:post-excerpt {\"excerptLength\":24,\"fontSize\":\"small\"} /-->\n		<!-- /wp:post-template -->\n		<!-- wp:query-no-results -->\n			<!-- wp:paragraph {\"className\":\"muted\"} --><p class=\"muted\">Case studies will appear here once published. Aim for six at launch — two per delivery mode.</p><!-- /wp:paragraph -->\n		<!-- /wp:query-no-results -->\n	</div>\n	<!-- /wp:query -->\n</div>\n<!-- /wp:group -->\n\n\n<!-- wp:academia/reviews-section /-->\n\n\n', 'Success Stories', '', 'inherit', 'closed', 'closed', '', '2137-revision-v1', '', '', '2026-08-23 22:58:07', '2026-08-23 22:58:07', '', 2137, 'https://academiatraining.eu/?p=2163', 0, 'revision', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(2164, 1, '2026-08-23 22:58:07', '2026-08-23 22:58:07', '<!-- wp:group {\"className\":\"hero\",\"layout\":{\"type\":\"constrained\"},\"align\":\"full\"} -->\n<div class=\"wp-block-group alignfull hero\">\n	<!-- wp:group {\"className\":\"wrap hero-inner\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group wrap hero-inner\">\n		<!-- wp:group {\"className\":\"stack gap-5\",\"layout\":{\"type\":\"default\"}} -->\n		<div class=\"wp-block-group stack gap-5\">\n			<!-- wp:paragraph {\"className\":\"is-style-academia-eyebrow\",\"style\":{\"color\":{\"text\":\"#E9C25A\"}}} --><p class=\"is-style-academia-eyebrow has-text-color\" style=\"color:#E9C25A\">Online training</p><!-- /wp:paragraph -->\n			<!-- wp:heading {\"level\":1,\"style\":{\"color\":{\"text\":\"#ffffff\"}}} --><h1 class=\"wp-block-heading has-text-color\" style=\"color:#ffffff\">Learn from anywhere. Nothing watered down.</h1><!-- /wp:heading -->\n			<!-- wp:paragraph {\"className\":\"lede\"} --><p class=\"lede\">Live, instructor-led virtual classrooms with the same experts, exercises and certificates as our classroom courses — plus recordings, labs and materials you keep. No travel, no hotel, no lost days.</p><!-- /wp:paragraph -->\n			<!-- wp:buttons -->\n			<div class=\"wp-block-buttons\">\n				<!-- wp:button {\"className\":\"is-style-academia-primary\"} --><div class=\"wp-block-button is-style-academia-primary\"><a class=\"wp-block-button__link wp-element-button\" href=\"/training-catalogue/?mode=online\">Browse online courses</a></div><!-- /wp:button -->\n				<!-- wp:button {\"className\":\"is-style-academia-on-dark\"} --><div class=\"wp-block-button is-style-academia-on-dark\"><a class=\"wp-block-button__link wp-element-button\" href=\"/training-schedule/?mode=online\">See online dates</a></div><!-- /wp:button -->\n			</div>\n			<!-- /wp:buttons -->\n		</div>\n		<!-- /wp:group -->\n		<!-- wp:group {\"className\":\"hero-art\",\"layout\":{\"type\":\"default\"}} -->\n		<div class=\"wp-block-group hero-art\">\n			<!-- wp:image {\"className\":\"is-style-academia-rounded\"} -->\n			<figure class=\"wp-block-image is-style-academia-rounded\"><img src=\"https://academiatraining.eu/wp-content/themes/academia-training/assets/img/mode-online.svg\" alt=\"Live virtual classroom with a grid of participants and an expert sharing their screen\"/></figure>\n			<!-- /wp:image -->\n		</div>\n		<!-- /wp:group -->\n	</div>\n	<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n\n\n<!-- wp:group {\"className\":\"section\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group section\">\n	<!-- wp:group {\"className\":\"sec-head\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group sec-head\">\n		<!-- wp:paragraph {\"className\":\"is-style-academia-eyebrow\"} --><p class=\"is-style-academia-eyebrow\">Why our online training works</p><!-- /wp:paragraph -->\n		<!-- wp:heading {\"level\":2} --><h2 class=\"wp-block-heading\">Designed for a screen, not squeezed onto one</h2><!-- /wp:heading -->\n		<!-- wp:paragraph {\"className\":\"is-style-academia-lede\"} --><p class=\"is-style-academia-lede\">Sessions run in shorter blocks with structured breaks, breakout rooms every 40 minutes and a maximum of 12 participants so nobody hides behind a switched-off camera.</p><!-- /wp:paragraph -->\n	</div>\n	<!-- /wp:group -->\n	<!-- wp:html -->\n	<div class=\"grid g3\">\n		<div class=\"card card-pad-lg\"><div class=\"cat-ico\" style=\"background:var(--gr-50);color:var(--gr-500)\"><svg><use href=\"#i-globe\"></use></svg></div><h4 style=\"margin-top:14px\">Learn from anywhere</h4><p class=\"small muted\">Join from the office, home or a client site. Nothing to install beyond a browser and a headset.</p></div>\n		<div class=\"card card-pad-lg\"><div class=\"cat-ico\" style=\"background:var(--o-50);color:var(--o-500)\"><svg><use href=\"#i-users\"></use></svg></div><h4 style=\"margin-top:14px\">Expert instructors, live</h4><p class=\"small muted\">The same practising specialists who teach our classroom courses. Questions answered in the moment, not in a forum.</p></div>\n		<div class=\"card card-pad-lg\"><div class=\"cat-ico\" style=\"background:var(--g-50);color:var(--g-600)\"><svg><use href=\"#i-people\"></use></svg></div><h4 style=\"margin-top:14px\">Real interaction</h4><p class=\"small muted\">Breakouts, polls, shared whiteboards and hands-on labs. Maximum 12 people per virtual classroom.</p></div>\n		<div class=\"card card-pad-lg\"><div class=\"cat-ico\" style=\"background:var(--o-50);color:var(--o-500)\"><svg><use href=\"#i-clock\"></use></svg></div><h4 style=\"margin-top:14px\">Flexible schedule</h4><p class=\"small muted\">Full days, half days or evening blocks across CET time zones — chosen so you can still do your job that week.</p></div>\n		<div class=\"card card-pad-lg\"><div class=\"cat-ico\" style=\"background:var(--gr-50);color:var(--gr-500)\"><svg><use href=\"#i-play\"></use></svg></div><h4 style=\"margin-top:14px\">Recorded resources</h4><p class=\"small muted\">Every session recorded and available for 90 days, with searchable transcripts and downloadable exercise files.</p></div>\n		<div class=\"card card-pad-lg\"><div class=\"cat-ico\" style=\"background:var(--g-50);color:var(--g-600)\"><svg><use href=\"#i-award\"></use></svg></div><h4 style=\"margin-top:14px\">Digital certificates</h4><p class=\"small muted\">Verifiable certificate issued automatically on completion, ready to add to your LinkedIn profile.</p></div>\n	</div>\n	<!-- /wp:html -->\n</div>\n<!-- /wp:group -->\n\n\n<!-- wp:group {\"className\":\"section\",\"backgroundColor\":\"brand-cream\",\"layout\":{\"type\":\"constrained\"},\"align\":\"full\"} -->\n<div class=\"wp-block-group alignfull section has-brand-cream-background-color has-background\">\n	<!-- wp:columns -->\n	<div class=\"wp-block-columns\">\n		<!-- wp:column {\"width\":\"38%\"} -->\n		<div class=\"wp-block-column\" style=\"flex-basis:38%\">\n			<!-- wp:paragraph {\"className\":\"is-style-academia-eyebrow\"} --><p class=\"is-style-academia-eyebrow\">A typical day</p><!-- /wp:paragraph -->\n			<!-- wp:heading {\"level\":2} --><h2 class=\"wp-block-heading\">What an online training day actually looks like</h2><!-- /wp:heading -->\n			<!-- wp:paragraph {\"className\":\"muted\"} --><p class=\"muted\">Times shown in CET. Half-day and evening variants are available for most courses, and in-company cohorts can set their own rhythm.</p><!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:column -->\n		<!-- wp:column {\"width\":\"62%\"} -->\n		<div class=\"wp-block-column\" style=\"flex-basis:62%\">\n			<!-- wp:html -->\n			<div class=\"card\" style=\"overflow:hidden\">\n				<table class=\"modtable\">\n					<thead><tr><th style=\"width:110px\">Time</th><th>Session</th><th style=\"width:150px\">Format</th></tr></thead>\n					<tbody>\n						<tr><td><b>08:45</b></td><td>Virtual room opens — tech check, coffee, introductions</td><td><span class=\"chip\">Optional</span></td></tr>\n						<tr><td><b>09:00</b></td><td>Block 1 — concept input and worked example</td><td><span class=\"chip chip-green\">Live</span></td></tr>\n						<tr><td><b>09:40</b></td><td>Breakout exercise in pairs, expert rotates between rooms</td><td><span class=\"chip chip-orange\">Hands-on</span></td></tr>\n						<tr><td><b>10:20</b></td><td>Break</td><td><span class=\"chip\">15 min</span></td></tr>\n						<tr><td><b>10:35</b></td><td>Block 2 — applying it to your own data or case</td><td><span class=\"chip chip-orange\">Hands-on</span></td></tr>\n						<tr><td><b>12:00</b></td><td>Lunch</td><td><span class=\"chip\">45 min</span></td></tr>\n						<tr><td><b>12:45</b></td><td>Block 3 — advanced techniques and pitfalls</td><td><span class=\"chip chip-green\">Live</span></td></tr>\n						<tr><td><b>14:15</b></td><td>Lab — guided practice in the sandbox environment</td><td><span class=\"chip chip-orange\">Hands-on</span></td></tr>\n						<tr><td><b>15:30</b></td><td>Q&amp;A on your own situations, action planning</td><td><span class=\"chip chip-green\">Live</span></td></tr>\n						<tr><td><b>16:30</b></td><td>Close — recording, materials and certificate issued</td><td><span class=\"chip chip-gold\">Wrap-up</span></td></tr>\n					</tbody>\n				</table>\n			</div>\n			<!-- /wp:html -->\n		</div>\n		<!-- /wp:column -->\n	</div>\n	<!-- /wp:columns -->\n</div>\n<!-- /wp:group -->\n\n\n<!-- wp:group {\"className\":\"section\",\"layout\":{\"type\":\"constrained\"},\"anchor\":\"self-paced\"} -->\n<div class=\"wp-block-group section\" id=\"self-paced\">\n	<!-- wp:group {\"className\":\"sec-head\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group sec-head\">\n		<!-- wp:paragraph {\"className\":\"is-style-academia-eyebrow\"} --><p class=\"is-style-academia-eyebrow\">Choose your format</p><!-- /wp:paragraph -->\n		<!-- wp:heading {\"level\":2} --><h2 class=\"wp-block-heading\">Live, self-paced, or a blend of both</h2><!-- /wp:heading -->\n	</div>\n	<!-- /wp:group -->\n	<!-- wp:html -->\n	<div class=\"grid g3\">\n		<div class=\"card card-pad-lg card-hover\">\n			<span class=\"chip chip-green\"><span class=\"dot\"></span> Most popular</span>\n			<h3 style=\"margin-top:12px\">Live virtual classroom</h3>\n			<p class=\"small muted\">Scheduled dates, real expert, real cohort. Best when you need to ask questions about your own situation.</p>\n			<ul class=\"mode-list\" style=\"margin-top:14px\">\n				<li><svg><use href=\"#i-check\"></use></svg> Max 12 participants</li>\n				<li><svg><use href=\"#i-check\"></use></svg> Recording for 90 days</li>\n				<li><svg><use href=\"#i-check\"></use></svg> Same certificate as classroom</li>\n			</ul>\n			<p class=\"price\" style=\"margin-top:16px\">from €690 <small>per person, per day, excl. VAT</small></p>\n		</div>\n		<div class=\"card card-pad-lg card-hover\">\n			<span class=\"chip\">Learn at your pace</span>\n			<h3 style=\"margin-top:12px\">Self-paced modules</h3>\n			<p class=\"small muted\">Video, exercises and knowledge checks you complete when it suits. Best for foundational and compliance topics.</p>\n			<ul class=\"mode-list\" style=\"margin-top:14px\">\n				<li><svg><use href=\"#i-check\"></use></svg> 12 months access</li>\n				<li><svg><use href=\"#i-check\"></use></svg> Progress tracking and quizzes</li>\n				<li><svg><use href=\"#i-check\"></use></svg> Team licences from 10 seats</li>\n			</ul>\n			<p class=\"price\" style=\"margin-top:16px\">from €245 <small>per person, per module, excl. VAT</small></p>\n		</div>\n		<div class=\"card card-pad-lg card-hover\">\n			<span class=\"chip chip-gold\">Best retention</span>\n			<h3 style=\"margin-top:12px\">Blended programme</h3>\n			<p class=\"small muted\">Self-paced groundwork, then live workshops for application and coaching. Best for larger cohorts and behaviour change.</p>\n			<ul class=\"mode-list\" style=\"margin-top:14px\">\n				<li><svg><use href=\"#i-check\"></use></svg> Pre-work, workshop, follow-up</li>\n				<li><svg><use href=\"#i-check\"></use></svg> Manager briefing pack included</li>\n				<li><svg><use href=\"#i-check\"></use></svg> Impact measured at 90 days</li>\n			</ul>\n			<p class=\"price\" style=\"margin-top:16px\">Quoted <small>per programme — request a proposal</small></p>\n		</div>\n	</div>\n	<!-- /wp:html -->\n</div>\n<!-- /wp:group -->\n\n\n<!-- wp:group {\"className\":\"section sec-sand\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group section sec-sand\">\n	<!-- wp:group {\"className\":\"sec-head\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group sec-head\">\n		<!-- wp:paragraph {\"className\":\"is-style-academia-eyebrow\"} --><p class=\"is-style-academia-eyebrow\">What participants tell us</p><!-- /wp:paragraph -->\n		<!-- wp:heading {\"level\":2} --><h2 class=\"wp-block-heading\">The feedback we design for</h2><!-- /wp:heading -->\n		<!-- wp:paragraph {\"className\":\"lede\"} --><p class=\"lede\">We do not publish attributed quotes, because we will not put a name and a face to words a participant did not write. What we can publish is the standard every programme is built to meet — and, below it, an independent review feed once participants have submitted their own.</p><!-- /wp:paragraph -->\n	</div>\n	<!-- /wp:group -->\n	<!-- wp:html -->\n	<div class=\"grid g3\">\n		<figure class=\"quote-card is-sample\">\n			<span class=\"sample-flag\">Illustrative</span>\n			<blockquote>Built something with our own company data on day one, and it was still in use two weeks later.</blockquote>\n			<figcaption class=\"who\"><span class=\"xs muted\">Data &amp; BI · classroom · the outcome this course is designed to produce</span></figcaption>\n		</figure>\n		<figure class=\"quote-card is-sample\">\n			<span class=\"sample-flag\">Illustrative</span>\n			<blockquote>Case studies adapted per market, and one consistent report on capability gaps across every site.</blockquote>\n			<figcaption class=\"who\"><span class=\"xs muted\">Leadership · multi-country in-company · what we contract to deliver</span></figcaption>\n		</figure>\n		<figure class=\"quote-card is-sample\">\n			<span class=\"sample-flag\">Illustrative</span>\n			<blockquote>Recordings and a real lab environment, so practising around a full-time job was actually possible.</blockquote>\n			<figcaption class=\"who\"><span class=\"xs muted\">Systems training · live online · the standard our online delivery is held to</span></figcaption>\n		</figure>\n	</div>\n	<!-- /wp:html -->\n\n	<!-- wp:academia/reviews-widget /-->\n\n	<!-- wp:paragraph {\"align\":\"center\",\"fontSize\":\"x-small\",\"className\":\"muted\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"22px\"}}}} -->\n	<p class=\"has-text-align-center muted has-x-small-font-size\" style=\"margin-top:22px\">Academia publishes no rating of its own. When an independent review platform is connected under Training → Settings, verified reviews and a verified score appear above — and only then does <code>aggregateRating</code> schema begin to emit.</p>\n	<!-- /wp:paragraph -->\n</div>\n<!-- /wp:group -->\n\n\n<!-- wp:template-part {\"slug\":\"cta-corporate\",\"tagName\":\"div\",\"theme\":\"academia-training\"} /-->\n\n\n', 'Online Training', '', 'inherit', 'closed', 'closed', '', '2136-revision-v1', '', '', '2026-08-23 22:58:07', '2026-08-23 22:58:07', '', 2136, 'https://academiatraining.eu/?p=2164', 0, 'revision', '', 0),
(2165, 1, '2026-08-23 22:58:07', '2026-08-23 22:58:07', '<!-- wp:group {\"className\":\"hero\",\"layout\":{\"type\":\"constrained\"},\"align\":\"full\"} -->\n<div class=\"wp-block-group alignfull hero\">\n	<!-- wp:group {\"className\":\"wrap hero-inner\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group wrap hero-inner\">\n		<!-- wp:group {\"className\":\"stack gap-5\",\"layout\":{\"type\":\"default\"}} -->\n		<div class=\"wp-block-group stack gap-5\">\n			<!-- wp:paragraph {\"className\":\"is-style-academia-eyebrow\",\"style\":{\"color\":{\"text\":\"#E9C25A\"}}} --><p class=\"is-style-academia-eyebrow has-text-color\" style=\"color:#E9C25A\">Corporate &amp; in-company training</p><!-- /wp:paragraph -->\n			<!-- wp:heading {\"level\":1,\"style\":{\"color\":{\"text\":\"#ffffff\"}}} --><h1 class=\"wp-block-heading has-text-color\" style=\"color:#ffffff\">Develop your workforce with practical, industry-relevant training</h1><!-- /wp:heading -->\n			<!-- wp:paragraph {\"className\":\"lede\"} --><p class=\"lede\">From a single team workshop to a multi-country capability programme. We assess the gap, design the curriculum around your systems and sector, deliver it wherever your people are, and report on what changed.</p><!-- /wp:paragraph -->\n			<!-- wp:list {\"className\":\"is-style-academia-checks\",\"style\":{\"color\":{\"text\":\"rgba(242,240,227,.86)\"}}} -->\n			<ul class=\"wp-block-list is-style-academia-checks has-text-color\" style=\"color:rgba(242,240,227,.86)\">\n				<li>Proposal within two working days, fixed price, no surprises</li>\n				<li>Delivered at your offices, live online, or in a private classroom in any European city</li>\n				<li>Training in English, Dutch, German, French, Spanish and Italian</li>\n				<li>One invoice, one point of contact, one capability report</li>\n			</ul>\n			<!-- /wp:list -->\n			<!-- wp:buttons -->\n			<div class=\"wp-block-buttons\">\n				<!-- wp:button {\"className\":\"is-style-academia-gold\"} --><div class=\"wp-block-button is-style-academia-gold\"><a class=\"wp-block-button__link wp-element-button\" href=\"#proposal\">Request corporate training proposal</a></div><!-- /wp:button -->\n				<!-- wp:button {\"className\":\"is-style-academia-on-dark\"} --><div class=\"wp-block-button is-style-academia-on-dark\"><a class=\"wp-block-button__link wp-element-button\" href=\"/contact/\">Book a 20-minute consultation</a></div><!-- /wp:button -->\n			</div>\n			<!-- /wp:buttons -->\n		</div>\n		<!-- /wp:group -->\n		<!-- wp:group {\"className\":\"hero-art\",\"layout\":{\"type\":\"default\"}} -->\n		<div class=\"wp-block-group hero-art\">\n			<!-- wp:image {\"className\":\"is-style-academia-rounded\"} -->\n			<figure class=\"wp-block-image is-style-academia-rounded\"><img src=\"https://academiatraining.eu/wp-content/themes/academia-training/assets/img/mode-onsite.svg\" alt=\"Trainer facilitating a workshop with a corporate team in their own meeting room\"/></figure>\n			<!-- /wp:image -->\n		</div>\n		<!-- /wp:group -->\n	</div>\n	<!-- /wp:group -->\n	<!-- wp:group {\"className\":\"stat-strip\",\"layout\":{\"type\":\"constrained\"},\"align\":\"full\"} -->\n	<div class=\"wp-block-group alignfull stat-strip\">\n		<!-- wp:academia/corporate-stats /-->\n	</div>\n	<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n\n\n<!-- wp:group {\"className\":\"section\",\"layout\":{\"type\":\"constrained\"},\"anchor\":\"customised\"} -->\n<div class=\"wp-block-group section\" id=\"customised\">\n	<!-- wp:group {\"className\":\"sec-head\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group sec-head\">\n		<!-- wp:paragraph {\"className\":\"is-style-academia-eyebrow\"} --><p class=\"is-style-academia-eyebrow\">What we deliver for organisations</p><!-- /wp:paragraph -->\n		<!-- wp:heading {\"level\":2} --><h2 class=\"wp-block-heading\">Built around your capability gap, not our catalogue</h2><!-- /wp:heading -->\n	</div>\n	<!-- /wp:group -->\n	<!-- wp:html -->\n	<div class=\"grid g3\">\n		<div class=\"card card-pad-lg card-hover\"><div class=\"cat-ico\" style=\"background:var(--o-50);color:var(--o-500)\"><svg><use href=\"#i-spark\"></use></svg></div><h4 style=\"margin-top:14px\">Customised training programmes</h4><p class=\"small muted\">We rewrite cases, data and exercises around your sector, your systems and your policies — so nothing has to be translated back into your context.</p></div>\n		<div class=\"card card-pad-lg card-hover\" id=\"assessment\"><div class=\"cat-ico\" style=\"background:var(--gr-50);color:var(--gr-500)\"><svg><use href=\"#i-chart\"></use></svg></div><h4 style=\"margin-top:14px\">Employee skills assessment</h4><p class=\"small muted\">Diagnostic before, measurement after. You get a heat map of capability by team and a defensible baseline for the training budget.</p></div>\n		<div class=\"card card-pad-lg card-hover\"><div class=\"cat-ico\" style=\"background:var(--g-50);color:var(--g-600)\"><svg><use href=\"#i-building\"></use></svg></div><h4 style=\"margin-top:14px\">Onsite workshops</h4><p class=\"small muted\">One to five days at your premises anywhere in Europe. Cost-effective from six participants and far easier to schedule.</p></div>\n		<div class=\"card card-pad-lg card-hover\"><div class=\"cat-ico\" style=\"background:var(--o-50);color:var(--o-500)\"><svg><use href=\"#i-users\"></use></svg></div><h4 style=\"margin-top:14px\">Leadership programmes</h4><p class=\"small muted\">Modular development journeys for first-time managers through to executive teams, with coaching and peer cohorts between modules.</p></div>\n		<div class=\"card card-pad-lg card-hover\"><div class=\"cat-ico\" style=\"background:var(--gr-50);color:var(--gr-500)\"><svg><use href=\"#i-code\"></use></svg></div><h4 style=\"margin-top:14px\">Technical &amp; systems training</h4><p class=\"small muted\">SAP, Power BI, Excel, Python, SQL and cloud — taught in a sandbox that mirrors your own environment.</p></div>\n		<div class=\"card card-pad-lg card-hover\"><div class=\"cat-ico\" style=\"background:var(--g-50);color:var(--g-600)\"><svg><use href=\"#i-globe\"></use></svg></div><h4 style=\"margin-top:14px\">Digital transformation training</h4><p class=\"small muted\">Change-ready programmes for ERP rollouts, AI adoption and process automation. Trains the behaviour, not just the button clicks.</p></div>\n		<div class=\"card card-pad-lg card-hover\"><div class=\"cat-ico\" style=\"background:var(--o-50);color:var(--o-500)\"><svg><use href=\"#i-people\"></use></svg></div><h4 style=\"margin-top:14px\">Team development</h4><p class=\"small muted\">Facilitated sessions on collaboration, communication and psychological safety — for teams that need to work differently, not know more.</p></div>\n		<div class=\"card card-pad-lg card-hover\"><div class=\"cat-ico\" style=\"background:var(--gr-50);color:var(--gr-500)\"><svg><use href=\"#i-award\"></use></svg></div><h4 style=\"margin-top:14px\">Certification pathways</h4><p class=\"small muted\">PRINCE2, PMP, Lean Six Sigma, ISO 27001, CIPS and more — exam preparation with pass-rate guarantees.</p></div>\n		<div class=\"card card-pad-lg card-hover\"><div class=\"cat-ico\" style=\"background:var(--g-50);color:var(--g-600)\"><svg><use href=\"#i-brief\"></use></svg></div><h4 style=\"margin-top:14px\">Annual training partnership</h4><p class=\"small muted\">A framework agreement with pre-agreed rates, a named advisor, seat pooling across the year and consolidated reporting.</p></div>\n	</div>\n	<!-- /wp:html -->\n</div>\n<!-- /wp:group -->\n\n\n<!-- wp:academia/skills-credits /-->\n\n\n<!-- wp:group {\"className\":\"section\",\"backgroundColor\":\"brand-cream\",\"layout\":{\"type\":\"constrained\"},\"align\":\"full\"} -->\n<div class=\"wp-block-group alignfull section has-brand-cream-background-color has-background\">\n	<!-- wp:columns -->\n	<div class=\"wp-block-columns\">\n		<!-- wp:column {\"width\":\"36%\"} -->\n		<div class=\"wp-block-column\" style=\"flex-basis:36%\">\n			<!-- wp:paragraph {\"className\":\"is-style-academia-eyebrow\"} --><p class=\"is-style-academia-eyebrow\">How it works</p><!-- /wp:paragraph -->\n			<!-- wp:heading {\"level\":2} --><h2 class=\"wp-block-heading\">From first call to measured outcome</h2><!-- /wp:heading -->\n			<!-- wp:paragraph {\"className\":\"muted\"} --><p class=\"muted\">Most corporate programmes go from enquiry to delivery in three to five weeks. Urgent requirements can move faster — tell us the deadline.</p><!-- /wp:paragraph -->\n		</div>\n		<!-- /wp:column -->\n		<!-- wp:column {\"width\":\"64%\"} -->\n		<div class=\"wp-block-column\" style=\"flex-basis:64%\">\n			<!-- wp:html -->\n			<div class=\"steps card card-pad-lg\">\n				<div class=\"step\"><span class=\"sn\">1</span><div><h4>Enquiry</h4><p class=\"small muted\">You send the requirement — team, topic, timing, budget range. Two minutes on the form below is enough.</p></div></div>\n				<div class=\"step\"><span class=\"sn\">2</span><div><h4>Consultation call</h4><p class=\"small muted\">20–30 minutes with a training advisor and, where useful, the expert who would deliver it. We challenge the brief if we think the real gap is elsewhere.</p></div></div>\n				<div class=\"step green\"><span class=\"sn\">3</span><div><h4>Proposal</h4><p class=\"small muted\">Curriculum outline, learning outcomes, expert profile, dates, logistics and a fixed price — within two working days.</p></div></div>\n				<div class=\"step green\"><span class=\"sn\">4</span><div><h4>Contract &amp; scheduling</h4><p class=\"small muted\">Framework or one-off agreement, purchase order, dates locked, joining instructions and pre-work sent to participants.</p></div></div>\n				<div class=\"step green\"><span class=\"sn\">5</span><div><h4>Delivery</h4><p class=\"small muted\">Onsite, online or private classroom. Attendance tracked, materials distributed digitally, certificates issued automatically.</p></div></div>\n				<div class=\"step green\"><span class=\"sn\">6</span><div><h4>Report &amp; follow-up</h4><p class=\"small muted\">Evaluation scores, capability heat map, expert observations and recommended next steps. Optional 90-day follow-up session.</p></div></div>\n			</div>\n			<!-- /wp:html -->\n		</div>\n		<!-- /wp:column -->\n	</div>\n	<!-- /wp:columns -->\n</div>\n<!-- /wp:group -->\n\n\n<!-- wp:academia/corporate-proof /-->\n\n\n<!-- wp:group {\"backgroundColor\":\"brand-cream\",\"layout\":{\"type\":\"constrained\"},\"align\":\"full\"} -->\n<div class=\"wp-block-group alignfull has-brand-cream-background-color has-background\">\n	<!-- wp:academia/value-comparison /-->\n</div>\n<!-- /wp:group -->\n\n\n<!-- wp:group {\"className\":\"section\",\"backgroundColor\":\"brand-brown\",\"layout\":{\"type\":\"constrained\"},\"align\":\"full\",\"anchor\":\"proposal\"} -->\n<div class=\"wp-block-group alignfull section has-brand-brown-background-color has-background\" id=\"proposal\">\n	<!-- wp:columns -->\n	<div class=\"wp-block-columns\">\n		<!-- wp:column {\"width\":\"40%\"} -->\n		<div class=\"wp-block-column\" style=\"flex-basis:40%\">\n			<!-- wp:paragraph {\"className\":\"is-style-academia-eyebrow\",\"style\":{\"color\":{\"text\":\"#E9C25A\"}}} --><p class=\"is-style-academia-eyebrow has-text-color\" style=\"color:#E9C25A\">Two minutes, no obligation</p><!-- /wp:paragraph -->\n			<!-- wp:heading {\"level\":2,\"style\":{\"color\":{\"text\":\"#ffffff\"}}} --><h2 class=\"wp-block-heading has-text-color\" style=\"color:#ffffff\">Request a corporate training proposal</h2><!-- /wp:heading -->\n			<!-- wp:paragraph {\"style\":{\"color\":{\"text\":\"rgba(242,240,227,.80)\"}}} -->\n			<p class=\"has-text-color\" style=\"color:rgba(242,240,227,.80)\">Tell us roughly what you need. A training advisor reviews every enquiry personally and comes back within two working days with an outline, an expert profile and a price.</p>\n			<!-- /wp:paragraph -->\n			<!-- wp:html -->\n			<div class=\"stack gap-3\" style=\"margin-top:24px;color:rgba(242,240,227,.86);font-size:14px\">\n				<span class=\"center gap-3\"><svg style=\"width:18px;height:18px;color:#6FAC91\"><use href=\"#i-checkc\"></use></svg> Fixed price — no per-participant surprises</span>\n				<span class=\"center gap-3\"><svg style=\"width:18px;height:18px;color:#6FAC91\"><use href=\"#i-checkc\"></use></svg> Your data stays in the EU, GDPR compliant</span>\n				<span class=\"center gap-3\"><svg style=\"width:18px;height:18px;color:#6FAC91\"><use href=\"#i-checkc\"></use></svg> We will say so if we are not the right provider</span>\n				<span class=\"center gap-3\"><svg style=\"width:18px;height:18px;color:#6FAC91\"><use href=\"#i-checkc\"></use></svg> [academia_phone prefix=\"Prefer to talk first? Call \"]</span>\n			</div>\n			<!-- /wp:html -->\n		</div>\n		<!-- /wp:column -->\n		<!-- wp:column {\"width\":\"60%\"} -->\n		<div class=\"wp-block-column\" style=\"flex-basis:60%\">\n			<!-- wp:academia/lead-form {\"formId\":\"corporate\",\"showEstimator\":true} /-->\n		</div>\n		<!-- /wp:column -->\n	</div>\n	<!-- /wp:columns -->\n</div>\n<!-- /wp:group -->\n\n\n<!-- wp:group {\"className\":\"section-sm\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group section-sm\">\n	<!-- wp:academia/callback /-->\n</div>\n<!-- /wp:group -->\n\n\n<!-- wp:group {\"className\":\"section\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group section\">\n	<!-- wp:heading {\"level\":2,\"className\":\"is-style-academia-underline\"} --><h2 class=\"wp-block-heading is-style-academia-underline\">Questions procurement usually asks</h2><!-- /wp:heading -->\n	<!-- wp:spacer {\"height\":\"28px\"} --><div style=\"height:28px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div><!-- /wp:spacer -->\n	<!-- wp:academia/faq {\"schema\":true,\"items\":[{\"q\":\"How is in-company training priced?\",\"a\":\"Per training day, not per participant — so the cost per head falls as the group grows. A one-day onsite workshop for up to 8 people starts at €2,950 excluding VAT and expert travel. Multi-module programmes and annual frameworks are quoted as a package.\"},{\"q\":\"What is the minimum group size?\",\"a\":\"Six participants makes in-company delivery cheaper than sending people to public courses. We will run smaller groups where the topic justifies it — an executive team of four, for example.\"},{\"q\":\"Can you deliver across several countries?\",\"a\":\"Yes. We regularly run the same programme across multiple sites in different countries. Delivery is in English throughout — the working language of almost every multi-country team we train — with case studies, regulation references and examples localised to each market, and one central report covering all sites.\"},{\"q\":\"Do you work with framework agreements and preferred-supplier lists?\",\"a\":\"Yes. We hold annual framework agreements with pre-agreed day rates, pooled seats and consolidated quarterly invoicing. We are happy to complete supplier onboarding, insurance and compliance questionnaires.\"},{\"q\":\"How do you handle our data?\",\"a\":\"Participant data is processed in the EU under a signed DPA, retained only as long as certification requires, and never used for marketing without consent. Our sub-processor list is available on request.\"},{\"q\":\"Can training be linked to our own LMS?\",\"a\":\"Yes. We can deliver SCORM/xAPI packages, push completion records into your LMS or HRIS via API, and issue certificates under your own branding.\"}]} /-->\n</div>\n<!-- /wp:group -->\n\n\n', 'Corporate Training', '', 'inherit', 'closed', 'closed', '', '2135-revision-v1', '', '', '2026-08-23 22:58:07', '2026-08-23 22:58:07', '', 2135, 'https://academiatraining.eu/?p=2165', 0, 'revision', '', 0),
(2166, 1, '2026-08-23 22:58:07', '2026-08-23 22:58:07', '<!-- wp:group {\"className\":\"hero\",\"layout\":{\"type\":\"constrained\"},\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|80\",\"bottom\":\"var:preset|spacing|80\"}}}} -->\n<div class=\"wp-block-group alignfull hero\" style=\"padding-top:var(--wp--preset--spacing--80);padding-bottom:var(--wp--preset--spacing--80)\">\n	<!-- wp:academia/breadcrumbs /-->\n	<!-- wp:columns {\"verticalAlignment\":\"center\"} -->\n	<div class=\"wp-block-columns are-vertically-aligned-center\">\n		<!-- wp:column {\"width\":\"58%\"} -->\n		<div class=\"wp-block-column\" style=\"flex-basis:58%\">\n			<!-- wp:paragraph {\"className\":\"is-style-academia-eyebrow\",\"style\":{\"color\":{\"text\":\"#E9C25A\"}}} --><p class=\"is-style-academia-eyebrow has-text-color\" style=\"color:#E9C25A\">Classroom training</p><!-- /wp:paragraph -->\n			<!-- wp:heading {\"level\":1,\"style\":{\"color\":{\"text\":\"#ffffff\"}}} --><h1 class=\"wp-block-heading has-text-color\" style=\"color:#ffffff\">Public courses in [academia_city_count] European cities</h1><!-- /wp:heading -->\n			<!-- wp:paragraph {\"className\":\"lede\"} --><p class=\"lede\">Central, well-connected venues within twenty minutes of the main station or airport. Small groups, proper equipment, decent coffee, and an expert who has done the job.</p><!-- /wp:paragraph -->\n			<!-- wp:buttons -->\n			<div class=\"wp-block-buttons\">\n				<!-- wp:button {\"className\":\"is-style-academia-primary\"} --><div class=\"wp-block-button is-style-academia-primary\"><a class=\"wp-block-button__link wp-element-button\" href=\"/training-schedule/\">See all dates</a></div><!-- /wp:button -->\n				<!-- wp:button {\"className\":\"is-style-academia-on-dark\"} --><div class=\"wp-block-button is-style-academia-on-dark\"><a class=\"wp-block-button__link wp-element-button\" href=\"/corporate-training/\">Book a private classroom</a></div><!-- /wp:button -->\n			</div>\n			<!-- /wp:buttons -->\n		</div>\n		<!-- /wp:column -->\n		<!-- wp:column {\"width\":\"42%\"} -->\n		<div class=\"wp-block-column\" style=\"flex-basis:42%\">\n			<!-- wp:academia/country-map {\"highlight\":\"all\"} /-->\n		</div>\n		<!-- /wp:column -->\n	</div>\n	<!-- /wp:columns -->\n</div>\n<!-- /wp:group -->\n\n\n<!-- wp:group {\"className\":\"section\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group section\">\n	<!-- wp:academia/city-grid {\"groupByCountry\":true,\"columns\":4} /-->\n</div>\n<!-- /wp:group -->\n\n\n<!-- wp:group {\"className\":\"section\",\"backgroundColor\":\"brand-cream\",\"layout\":{\"type\":\"constrained\"},\"align\":\"full\"} -->\n<div class=\"wp-block-group alignfull section has-brand-cream-background-color has-background\">\n	<!-- wp:group {\"className\":\"sec-head\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group sec-head\">\n		<!-- wp:paragraph {\"className\":\"is-style-academia-eyebrow\"} --><p class=\"is-style-academia-eyebrow\">The same standard everywhere</p><!-- /wp:paragraph -->\n		<!-- wp:heading {\"level\":2} --><h2 class=\"wp-block-heading\">What every Academia classroom includes</h2><!-- /wp:heading -->\n	</div>\n	<!-- /wp:group -->\n	<!-- wp:html -->\n	<div class=\"grid g4\">\n		<div class=\"card card-body\"><div class=\"cat-ico\" style=\"background:var(--o-50);color:var(--o-500)\"><svg><use href=\"#i-pin\"></use></svg></div><h4 style=\"margin-top:12px\">Central location</h4><p class=\"small muted\">Within 20 minutes of the central station, with parking and hotels nearby.</p></div>\n		<div class=\"card card-body\"><div class=\"cat-ico\" style=\"background:var(--gr-50);color:var(--gr-500)\"><svg><use href=\"#i-monitor\"></use></svg></div><h4 style=\"margin-top:12px\">Full equipment</h4><p class=\"small muted\">Laptop per participant where the course needs one, dual screens for technical labs, fast Wi-Fi.</p></div>\n		<div class=\"card card-body\"><div class=\"cat-ico\" style=\"background:var(--g-50);color:var(--g-600)\"><svg><use href=\"#i-people\"></use></svg></div><h4 style=\"margin-top:12px\">Maximum 14 seats</h4><p class=\"small muted\">Room laid out for group work, not lecture rows. Everyone is within speaking distance of the expert.</p></div>\n		<div class=\"card card-body\"><div class=\"cat-ico\" style=\"background:var(--o-50);color:var(--o-500)\"><svg><use href=\"#i-check\"></use></svg></div><h4 style=\"margin-top:12px\">Catering included</h4><p class=\"small muted\">Lunch, refreshments and dietary requirements handled. No hidden extras on the invoice.</p></div>\n	</div>\n	<!-- /wp:html -->\n</div>\n<!-- /wp:group -->\n\n\n<!-- wp:template-part {\"slug\":\"cta-corporate\",\"tagName\":\"div\",\"theme\":\"academia-training\"} /-->\n\n\n', 'Classroom Training Across Europe', '', 'inherit', 'closed', 'closed', '', '2134-revision-v1', '', '', '2026-08-23 22:58:07', '2026-08-23 22:58:07', '', 2134, 'https://academiatraining.eu/?p=2166', 0, 'revision', '', 0);
INSERT INTO `wp_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(2167, 1, '2026-08-23 22:58:07', '2026-08-23 22:58:07', '<!-- wp:group {\"className\":\"hero\",\"layout\":{\"type\":\"constrained\"},\"align\":\"full\"} -->\n<div class=\"wp-block-group alignfull hero\">\n	<!-- wp:group {\"className\":\"wrap hero-inner\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group wrap hero-inner\">\n\n		<!-- wp:group {\"className\":\"stack gap-5\",\"layout\":{\"type\":\"default\"}} -->\n		<div class=\"wp-block-group stack gap-5\">\n			<!-- wp:group {\"className\":\"badge-row\",\"layout\":{\"type\":\"flex\",\"flexWrap\":\"wrap\"}} -->\n			<div class=\"wp-block-group badge-row\">\n				<!-- wp:html --><span class=\"hbadge\"><svg style=\"width:14px;height:14px\"><use href=\"#i-people\"></use></svg> Maximum 14 per classroom</span><!-- /wp:html -->\n				<!-- wp:html --><span class=\"hbadge\"><svg style=\"width:14px;height:14px\"><use href=\"#i-award\"></use></svg> Every expert 10+ years, still practising</span><!-- /wp:html -->\n				<!-- wp:html --><span class=\"hbadge\"><svg style=\"width:14px;height:14px\"><use href=\"#i-globe\"></use></svg> Delivered in English across [academia_city_count] European cities</span><!-- /wp:html -->\n			</div>\n			<!-- /wp:group -->\n\n			<!-- wp:heading {\"level\":1} -->\n			<h1 class=\"wp-block-heading\">Transform skills. Empower careers.<br><em>Build future-ready teams.</em></h1>\n			<!-- /wp:heading -->\n\n			<!-- wp:paragraph {\"className\":\"lede\"} -->\n			<p class=\"lede\">Professional online, onsite and classroom training delivered by practising subject matter experts across Europe. Over 500 courses in business, finance, technology, supply chain, HR and compliance.</p>\n			<!-- /wp:paragraph -->\n\n			<!-- wp:academia/course-search {\"variant\":\"hero\"} /-->\n\n			<!-- wp:group {\"className\":\"suggests\",\"layout\":{\"type\":\"flex\",\"flexWrap\":\"wrap\"}} -->\n			<div class=\"wp-block-group suggests\">\n				<!-- wp:html --><span>Popular right now:</span>\n				<a class=\"stag\" href=\"/training-catalogue/?q=SAP+S%2F4HANA\">SAP S/4HANA</a>\n				<a class=\"stag\" href=\"/training-catalogue/?q=Power+BI\">Power BI</a>\n				<a class=\"stag\" href=\"/training-catalogue/?q=Leadership\">Leadership</a>\n				<a class=\"stag\" href=\"/training-catalogue/?q=IFRS\">IFRS</a>\n				<a class=\"stag\" href=\"/training-catalogue/?q=Generative+AI\">Generative AI</a>\n				<a class=\"stag\" href=\"/training-catalogue/?q=GDPR\">GDPR</a><!-- /wp:html -->\n			</div>\n			<!-- /wp:group -->\n\n			<!-- wp:buttons {\"style\":{\"spacing\":{\"margin\":{\"top\":\"10px\"}}}} -->\n			<div class=\"wp-block-buttons\" style=\"margin-top:10px\">\n				<!-- wp:button {\"className\":\"is-style-academia-primary\"} --><div class=\"wp-block-button is-style-academia-primary\"><a class=\"wp-block-button__link wp-element-button\" href=\"/training-catalogue/\">Browse 500+ courses</a></div><!-- /wp:button -->\n				<!-- wp:button {\"className\":\"is-style-academia-gold\"} --><div class=\"wp-block-button is-style-academia-gold\"><a class=\"wp-block-button__link wp-element-button\" href=\"/corporate-training/\">Corporate training enquiry</a></div><!-- /wp:button -->\n				<!-- wp:button {\"className\":\"is-style-academia-on-dark\"} --><div class=\"wp-block-button is-style-academia-on-dark\"><a class=\"wp-block-button__link wp-element-button\" href=\"/classroom-training-europe/\">Classroom locations</a></div><!-- /wp:button -->\n			</div>\n			<!-- /wp:buttons -->\n		</div>\n		<!-- /wp:group -->\n\n		<!-- wp:group {\"className\":\"hero-art\",\"layout\":{\"type\":\"default\"}} -->\n		<div class=\"wp-block-group hero-art\">\n			<!-- wp:image {\"sizeSlug\":\"academia-hero\",\"className\":\"is-style-academia-rounded\",\"style\":{\"border\":{\"radius\":\"20px\"}}} -->\n			<figure class=\"wp-block-image size-academia-hero is-style-academia-rounded\" style=\"border-radius:20px\">\n				<img src=\"https://academiatraining.eu/wp-content/themes/academia-training/assets/img/hero-collage.svg\" alt=\"Professionals learning together in a modern classroom, a live virtual session and an onsite corporate workshop\"/>\n			</figure>\n			<!-- /wp:image -->\n		</div>\n		<!-- /wp:group -->\n\n	</div>\n	<!-- /wp:group -->\n\n	<!-- wp:group {\"className\":\"stat-strip\",\"layout\":{\"type\":\"constrained\"},\"align\":\"full\"} -->\n	<div class=\"wp-block-group alignfull stat-strip\">\n		<!-- wp:academia/hero-stats /-->\n	</div>\n	<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n\n\n<!-- wp:group {\"className\":\"logoband\",\"layout\":{\"type\":\"constrained\"},\"align\":\"full\"} -->\n<div class=\"wp-block-group alignfull logoband\">\n	<!-- wp:html -->\n	<div class=\"wrap\"><span class=\"lbl\">Trusted by L&amp;D teams at</span>\n	<span class=\"clogo\"><span class=\"m\"></span>ABN AMRO</span>\n	<span class=\"clogo\"><span class=\"m\"></span>Everlam</span>\n	<span class=\"clogo\"><span class=\"m\"></span>OEG Group</span>\n	<span class=\"clogo\"><span class=\"m\"></span>Recharge Infra</span>\n	<span class=\"clogo\"><span class=\"m\"></span>Allseas</span>\n	<span class=\"clogo\"><span class=\"m\"></span>Urban Outfitters</span>\n	<span class=\"clogo\"><span class=\"m\"></span>GXO</span>\n	<span class=\"clogo\"><span class=\"m\"></span>Geodis</span>\n	<span class=\"clogo\"><span class=\"m\"></span>Colliers</span>\n	<span class=\"clogo\"><span class=\"m\"></span>Black Sea Trade &amp; Development Bank</span>\n	<span class=\"clogo\"><span class=\"m\"></span>Spectrum</span>\n	<span class=\"clogo\"><span class=\"m\"></span><span class=\"nb\">Transition&nbsp;Hero</span></span>\n	<span class=\"clogo\"><span class=\"m\"></span>Blue Digital Studio</span>\n	<span class=\"clogo\"><span class=\"m\"></span>Vena Energy</span>\n	<span class=\"clogo\"><span class=\"m\"></span>QA Systems</span></div>\n	<!-- /wp:html -->\n	\n</div>\n<!-- /wp:group -->\n\n\n<!-- wp:academia/offers-band /-->\n\n\n<!-- wp:group {\"className\":\"section\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group section\">\n	<!-- wp:group {\"className\":\"sec-head\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group sec-head\">\n		<!-- wp:paragraph {\"className\":\"is-style-academia-eyebrow\"} --><p class=\"is-style-academia-eyebrow\">How you learn with us</p><!-- /wp:paragraph -->\n		<!-- wp:heading {\"level\":2} --><h2 class=\"wp-block-heading\">Three ways to train. One standard of quality.</h2><!-- /wp:heading -->\n		<!-- wp:paragraph {\"className\":\"is-style-academia-lede\"} --><p class=\"is-style-academia-lede\">Every course in our catalogue can be delivered live online, at your own offices, or in a public classroom in a European city near you. Same expert, same materials, same certificate.</p><!-- /wp:paragraph -->\n	</div>\n	<!-- /wp:group -->\n\n	<!-- wp:columns -->\n	<div class=\"wp-block-columns\">\n		<!-- wp:column -->\n		<div class=\"wp-block-column\">\n			<!-- wp:html -->\n			<article class=\"card card-hover mode-card\">\n				<div class=\"mode-top\" style=\"background:linear-gradient(140deg,#2E6B4F,#1B4030)\">\n					<img src=\"https://academiatraining.eu/wp-content/themes/academia-training/assets/img/mode-online.svg\" alt=\"Live virtual classroom with participants on screen\" loading=\"lazy\">\n				</div>\n				<div class=\"card-body\">\n					<span class=\"chip chip-green\"><span class=\"dot\"></span> Live online</span>\n					<h3>Online Training</h3>\n					<p class=\"small muted\">Instructor-led virtual classrooms and self-paced modules. Join from anywhere in Europe with no travel cost.</p>\n					<ul class=\"mode-list\">\n						<li><svg><use href=\"#i-check\"></use></svg> Live interaction, breakout rooms and exercises</li>\n						<li><svg><use href=\"#i-check\"></use></svg> Sessions recorded for 90 days</li>\n						<li><svg><use href=\"#i-check\"></use></svg> Digital certificate on completion</li>\n					</ul>\n					<a class=\"link\" href=\"/online-training/\">Explore online training <svg><use href=\"#i-arrow\"></use></svg></a>\n				</div>\n			</article>\n			<!-- /wp:html -->\n		</div>\n		<!-- /wp:column -->\n		<!-- wp:column -->\n		<div class=\"wp-block-column\">\n			<!-- wp:html -->\n			<article class=\"card card-hover mode-card\">\n				<div class=\"mode-top\" style=\"background:linear-gradient(140deg,#B14705,#753003)\">\n					<img src=\"https://academiatraining.eu/wp-content/themes/academia-training/assets/img/mode-onsite.svg\" alt=\"Trainer running a workshop in a client\'s meeting room\" loading=\"lazy\">\n				</div>\n				<div class=\"card-body\">\n					<span class=\"chip chip-orange\"><span class=\"dot\"></span> In-company</span>\n					<h3>Onsite Corporate Training</h3>\n					<p class=\"small muted\">Your expert travels to you. Content built around your systems, your data and your team\'s real work.</p>\n					<ul class=\"mode-list\">\n						<li><svg><use href=\"#i-check\"></use></svg> Fully customised curriculum</li>\n						<li><svg><use href=\"#i-check\"></use></svg> Pre-training skills assessment</li>\n						<li><svg><use href=\"#i-check\"></use></svg> Cost-effective from 6 participants</li>\n					</ul>\n					<a class=\"link\" href=\"/corporate-training/\">Request a proposal <svg><use href=\"#i-arrow\"></use></svg></a>\n				</div>\n			</article>\n			<!-- /wp:html -->\n		</div>\n		<!-- /wp:column -->\n		<!-- wp:column -->\n		<div class=\"wp-block-column\">\n			<!-- wp:html -->\n			<article class=\"card card-hover mode-card\">\n				<div class=\"mode-top\" style=\"background:linear-gradient(140deg,#E0A526,#9C6E0F)\">\n					<img src=\"https://academiatraining.eu/wp-content/themes/academia-training/assets/img/mode-classroom.svg\" alt=\"Public classroom course in a modern European training venue\" loading=\"lazy\">\n				</div>\n				<div class=\"card-body\">\n					<span class=\"chip chip-gold\"><span class=\"dot\"></span> Public courses</span>\n					<h3>Classroom Training</h3>\n					<p class=\"small muted\">Scheduled public courses in [academia_city_count] European cities. Learn alongside professionals from other organisations.</p>\n					<ul class=\"mode-list\">\n						<li><svg><use href=\"#i-check\"></use></svg> Central, well-connected venues</li>\n						<li><svg><use href=\"#i-check\"></use></svg> Small groups, maximum 14 people</li>\n						<li><svg><use href=\"#i-check\"></use></svg> Lunch and materials included</li>\n					</ul>\n					<a class=\"link\" href=\"/classroom-training-europe/\">See locations and dates <svg><use href=\"#i-arrow\"></use></svg></a>\n				</div>\n			</article>\n			<!-- /wp:html -->\n		</div>\n		<!-- /wp:column -->\n	</div>\n	<!-- /wp:columns -->\n</div>\n<!-- /wp:group -->\n\n\n<!-- wp:group {\"className\":\"section\",\"backgroundColor\":\"brand-cream\",\"layout\":{\"type\":\"constrained\"},\"align\":\"full\"} -->\n<div class=\"wp-block-group alignfull section has-brand-cream-background-color has-background\">\n	<!-- wp:group {\"className\":\"between\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group between\">\n		<!-- wp:group {\"className\":\"sec-head\",\"layout\":{\"type\":\"default\"},\"style\":{\"spacing\":{\"margin\":{\"bottom\":\"0\"}}}} -->\n		<div class=\"wp-block-group sec-head\" style=\"margin-bottom:0\">\n			<!-- wp:paragraph {\"className\":\"is-style-academia-eyebrow\"} --><p class=\"is-style-academia-eyebrow\">500+ training topics</p><!-- /wp:paragraph -->\n			<!-- wp:heading {\"level\":2} --><h2 class=\"wp-block-heading\">Find training by subject area</h2><!-- /wp:heading -->\n		</div>\n		<!-- /wp:group -->\n		<!-- wp:buttons -->\n		<div class=\"wp-block-buttons\"><!-- wp:button {\"className\":\"is-style-academia-ghost\",\"fontSize\":\"small\"} --><div class=\"wp-block-button has-custom-font-size is-style-academia-ghost has-small-font-size\"><a class=\"wp-block-button__link wp-element-button\" href=\"/training-catalogue/\">View the full catalogue</a></div><!-- /wp:button --></div>\n		<!-- /wp:buttons -->\n	</div>\n	<!-- /wp:group -->\n\n	<!-- wp:spacer {\"height\":\"32px\"} --><div style=\"height:32px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div><!-- /wp:spacer -->\n	<!-- wp:academia/category-grid {\"columns\":3,\"showSubs\":true,\"showCounts\":true} /-->\n</div>\n<!-- /wp:group -->\n\n\n<!-- wp:group {\"className\":\"section\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group section\">\n	<!-- wp:group {\"className\":\"sec-head\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group sec-head\">\n		<!-- wp:paragraph {\"className\":\"is-style-academia-eyebrow\"} --><p class=\"is-style-academia-eyebrow\">Booking fast</p><!-- /wp:paragraph -->\n		<!-- wp:heading {\"level\":2} --><h2 class=\"wp-block-heading\">Courses professionals are booking this quarter</h2><!-- /wp:heading -->\n	</div>\n	<!-- /wp:group -->\n	<!-- wp:academia/course-rail {\"source\":\"popular\",\"count\":8,\"showTabs\":true} /-->\n</div>\n<!-- /wp:group -->\n\n\n<!-- wp:group {\"className\":\"section\",\"backgroundColor\":\"brand-brown\",\"textColor\":\"brand-cream\",\"layout\":{\"type\":\"constrained\"},\"align\":\"full\"} -->\n<div class=\"wp-block-group alignfull section has-brand-cream-color has-brand-brown-background-color has-text-color has-background\">\n	<!-- wp:group {\"className\":\"between\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group between\">\n		<!-- wp:group {\"layout\":{\"type\":\"default\"}} -->\n		<div class=\"wp-block-group\">\n			<!-- wp:paragraph {\"className\":\"is-style-academia-eyebrow\",\"style\":{\"color\":{\"text\":\"#E9C25A\"}}} --><p class=\"is-style-academia-eyebrow has-text-color\" style=\"color:#E9C25A\">Next dates</p><!-- /wp:paragraph -->\n			<!-- wp:heading {\"level\":2,\"style\":{\"color\":{\"text\":\"#ffffff\"}}} --><h2 class=\"wp-block-heading has-text-color\" style=\"color:#ffffff\">Starting soon across Europe</h2><!-- /wp:heading -->\n		</div>\n		<!-- /wp:group -->\n		<!-- wp:buttons -->\n		<div class=\"wp-block-buttons\"><!-- wp:button {\"className\":\"is-style-academia-on-dark\",\"fontSize\":\"small\"} --><div class=\"wp-block-button has-custom-font-size is-style-academia-on-dark has-small-font-size\"><a class=\"wp-block-button__link wp-element-button\" href=\"/training-schedule/\">Open the full calendar</a></div><!-- /wp:button --></div>\n		<!-- /wp:buttons -->\n	</div>\n	<!-- /wp:group -->\n	<!-- wp:spacer {\"height\":\"28px\"} --><div style=\"height:28px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div><!-- /wp:spacer -->\n	<!-- wp:academia/schedule {\"view\":\"list\",\"count\":8,\"showFilters\":false,\"theme\":\"dark\"} /-->\n</div>\n<!-- /wp:group -->\n\n\n<!-- wp:group {\"className\":\"section\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group section\">\n	<!-- wp:columns {\"verticalAlignment\":\"top\"} -->\n	<div class=\"wp-block-columns are-vertically-aligned-top\">\n		<!-- wp:column {\"width\":\"38%\"} -->\n		<div class=\"wp-block-column\" style=\"flex-basis:38%\">\n			<!-- wp:paragraph {\"className\":\"is-style-academia-eyebrow\"} --><p class=\"is-style-academia-eyebrow\">Why Academia</p><!-- /wp:paragraph -->\n			<!-- wp:heading {\"level\":2} --><h2 class=\"wp-block-heading\">Training that survives contact with Monday morning</h2><!-- /wp:heading -->\n			<!-- wp:paragraph {\"className\":\"is-style-academia-lede\"} --><p class=\"is-style-academia-lede\">We are not a content library. Every programme is taught live by someone who has done the job, and built around what your people have to deliver when they get back to their desks.</p><!-- /wp:paragraph -->\n			<!-- wp:buttons --><div class=\"wp-block-buttons\"><!-- wp:button {\"className\":\"is-style-academia-ghost\"} --><div class=\"wp-block-button is-style-academia-ghost\"><a class=\"wp-block-button__link wp-element-button\" href=\"/about/\">How we design our training</a></div><!-- /wp:button --></div><!-- /wp:buttons -->\n		</div>\n		<!-- /wp:column -->\n		<!-- wp:column {\"width\":\"62%\"} -->\n		<div class=\"wp-block-column\" style=\"flex-basis:62%\">\n			<!-- wp:html -->\n			<div class=\"grid g2\">\n				<div class=\"card card-pad-lg\">\n					<div class=\"cat-ico\" style=\"background:var(--o-50);color:var(--o-500)\"><svg><use href=\"#i-users\"></use></svg></div>\n					<h4 style=\"margin-top:14px\">Practitioners, not presenters</h4>\n					<p class=\"small muted\">Every expert has 10+ years in the field they teach and is still working in it. They bring live case material, not slideware.</p>\n				</div>\n				<div class=\"card card-pad-lg\">\n					<div class=\"cat-ico\" style=\"background:var(--gr-50);color:var(--gr-500)\"><svg><use href=\"#i-people\"></use></svg></div>\n					<h4 style=\"margin-top:14px\">Maximum 14 per classroom</h4>\n					<p class=\"small muted\">Small cohorts mean everyone gets airtime, feedback, and answers to their own situation.</p>\n				</div>\n				<div class=\"card card-pad-lg\">\n					<div class=\"cat-ico\" style=\"background:var(--g-50);color:var(--g-600)\"><svg><use href=\"#i-dl\"></use></svg></div>\n					<h4 style=\"margin-top:14px\">You leave with the toolkit</h4>\n					<p class=\"small muted\">Templates, checklists, models and calculators you can use the same week — not a certificate alone.</p>\n				</div>\n				<div class=\"card card-pad-lg\">\n					<div class=\"cat-ico\" style=\"background:var(--o-50);color:var(--o-500)\"><svg><use href=\"#i-shield\"></use></svg></div>\n					<h4 style=\"margin-top:14px\">Satisfaction guarantee</h4>\n					<p class=\"small muted\">If a course does not meet the objectives we agreed, you attend again at no cost. We rarely need to.</p>\n				</div>\n			</div>\n			<!-- /wp:html -->\n		</div>\n		<!-- /wp:column -->\n	</div>\n	<!-- /wp:columns -->\n</div>\n<!-- /wp:group -->\n\n\n<!-- wp:group {\"className\":\"section\",\"backgroundColor\":\"brand-cream\",\"layout\":{\"type\":\"constrained\"},\"align\":\"full\"} -->\n<div class=\"wp-block-group alignfull section has-brand-cream-background-color has-background\">\n	<!-- wp:columns {\"verticalAlignment\":\"top\"} -->\n	<div class=\"wp-block-columns are-vertically-aligned-top\">\n		<!-- wp:column {\"width\":\"42%\"} -->\n		<div class=\"wp-block-column\" style=\"flex-basis:42%\">\n			<!-- wp:paragraph {\"className\":\"is-style-academia-eyebrow\"} --><p class=\"is-style-academia-eyebrow\">Who teaches you</p><!-- /wp:paragraph -->\n			<!-- wp:heading {\"level\":2} --><h2 class=\"wp-block-heading\">A subject matter expert, not a career trainer</h2><!-- /wp:heading -->\n			<!-- wp:paragraph {\"className\":\"is-style-academia-lede\"} -->\n			<p class=\"is-style-academia-lede\">Every programme is delivered by a practising specialist with more than ten years in the field they teach. We match the expert to your subject, your sector and your language — and we introduce them to you by name, with their full profile, once your booking is confirmed.</p>\n			<!-- /wp:paragraph -->\n			<!-- wp:paragraph {\"className\":\"muted\",\"fontSize\":\"small\"} -->\n			<p class=\"muted has-small-font-size\">We do not publish expert identities before booking. It protects our specialists from being approached directly, and it keeps the match honest: you are matched to the right expert for your cohort, not sold the one whose photograph you liked.</p>\n			<!-- /wp:paragraph -->\n			<!-- wp:buttons -->\n			<div class=\"wp-block-buttons\">\n				<!-- wp:button {\"className\":\"is-style-academia-ghost\"} --><div class=\"wp-block-button is-style-academia-ghost\"><a class=\"wp-block-button__link wp-element-button\" href=\"/about/#experts\">How we select experts</a></div><!-- /wp:button -->\n				<!-- wp:button {\"className\":\"is-style-academia-green\"} --><div class=\"wp-block-button is-style-academia-green\"><a class=\"wp-block-button__link wp-element-button\" href=\"/corporate-training/#proposal\">Ask about your subject</a></div><!-- /wp:button -->\n			</div>\n			<!-- /wp:buttons -->\n		</div>\n		<!-- /wp:column -->\n		<!-- wp:column {\"width\":\"58%\"} -->\n		<div class=\"wp-block-column\" style=\"flex-basis:58%\">\n			<!-- wp:html -->\n			<div class=\"grid g2\">\n				<div class=\"card card-pad-lg\">\n					<div class=\"cat-ico\" style=\"background:var(--o-50);color:var(--o-500)\"><svg><use href=\"#i-award\"></use></svg></div>\n					<h4 style=\"margin-top:14px\">10+ years, minimum</h4>\n					<p class=\"small muted\">Nobody teaches a subject they have not practised. The average across our pool is 17 years in the role.</p>\n				</div>\n				<div class=\"card card-pad-lg\">\n					<div class=\"cat-ico\" style=\"background:var(--gr-50);color:var(--gr-500)\"><svg><use href=\"#i-brief\"></use></svg></div>\n					<h4 style=\"margin-top:14px\">Still doing the job</h4>\n					<p class=\"small muted\">Our experts consult, audit and build for a living. The case material in your session is from this year, not a textbook.</p>\n				</div>\n				<div class=\"card card-pad-lg\">\n					<div class=\"cat-ico\" style=\"background:var(--g-50);color:var(--g-600)\"><svg><use href=\"#i-shield\"></use></svg></div>\n					<h4 style=\"margin-top:14px\">One in twelve accepted</h4>\n					<p class=\"small muted\">Credential check, reference check and a teaching audition in front of a real cohort before anyone gets a class.</p>\n				</div>\n				<div class=\"card card-pad-lg\">\n					<div class=\"cat-ico\" style=\"background:var(--o-50);color:var(--o-500)\"><svg><use href=\"#i-user\"></use></svg></div>\n					<h4 style=\"margin-top:14px\">Introduced after booking</h4>\n					<p class=\"small muted\">Once your date is confirmed you receive your expert’s name, profile, certifications and a short intro call if you want one.</p>\n				</div>\n			</div>\n			<!-- /wp:html -->\n		</div>\n		<!-- /wp:column -->\n	</div>\n	<!-- /wp:columns -->\n</div>\n<!-- /wp:group -->\n\n\n<!-- wp:academia/reviews-section /-->\n\n\n<!-- wp:group {\"className\":\"section\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group section\">\n	<!-- wp:group {\"className\":\"between\",\"layout\":{\"type\":\"default\"}} -->\n	<div class=\"wp-block-group between\">\n		<!-- wp:group {\"className\":\"sec-head\",\"layout\":{\"type\":\"default\"},\"style\":{\"spacing\":{\"margin\":{\"bottom\":\"0\"}}}} -->\n		<div class=\"wp-block-group sec-head\" style=\"margin-bottom:0\">\n			<!-- wp:paragraph {\"className\":\"is-style-academia-eyebrow\"} --><p class=\"is-style-academia-eyebrow\">Classroom training across Europe</p><!-- /wp:paragraph -->\n			<!-- wp:heading {\"level\":2} --><h2 class=\"wp-block-heading\">Learn in a city near you</h2><!-- /wp:heading -->\n		</div>\n		<!-- /wp:group -->\n		<!-- wp:buttons --><div class=\"wp-block-buttons\"><!-- wp:button {\"className\":\"is-style-academia-ghost\",\"fontSize\":\"small\"} --><div class=\"wp-block-button has-custom-font-size is-style-academia-ghost has-small-font-size\"><a class=\"wp-block-button__link wp-element-button\" href=\"/classroom-training-europe/\">All [academia_city_count] locations</a></div><!-- /wp:button --></div><!-- /wp:buttons -->\n	</div>\n	<!-- /wp:group -->\n	<!-- wp:spacer {\"height\":\"32px\"} --><div style=\"height:32px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div><!-- /wp:spacer -->\n	<!-- wp:academia/city-grid {\"count\":8,\"columns\":4} /-->\n</div>\n<!-- /wp:group -->\n\n\n<!-- wp:template-part {\"slug\":\"cta-corporate\",\"tagName\":\"div\",\"theme\":\"academia-training\"} /-->\n\n\n<!-- wp:group {\"className\":\"section\",\"backgroundColor\":\"brand-cream\",\"layout\":{\"type\":\"constrained\"},\"align\":\"full\"} -->\n<div class=\"wp-block-group alignfull section has-brand-cream-background-color has-background\">\n	<!-- wp:columns -->\n	<div class=\"wp-block-columns\">\n		<!-- wp:column {\"width\":\"36%\"} -->\n		<div class=\"wp-block-column\" style=\"flex-basis:36%\">\n			<!-- wp:paragraph {\"className\":\"is-style-academia-eyebrow\"} --><p class=\"is-style-academia-eyebrow\">Good to know</p><!-- /wp:paragraph -->\n			<!-- wp:heading {\"level\":2} --><h2 class=\"wp-block-heading\">Frequently asked questions</h2><!-- /wp:heading -->\n			<!-- wp:paragraph {\"className\":\"muted\",\"fontSize\":\"small\"} --><p class=\"muted has-small-font-size\">Cannot find your answer? A training advisor replies within one working day.</p><!-- /wp:paragraph -->\n			<!-- wp:buttons --><div class=\"wp-block-buttons\"><!-- wp:button {\"className\":\"is-style-academia-ghost\",\"fontSize\":\"small\"} --><div class=\"wp-block-button has-custom-font-size is-style-academia-ghost has-small-font-size\"><a class=\"wp-block-button__link wp-element-button\" href=\"/contact/\">Ask a question</a></div><!-- /wp:button --></div><!-- /wp:buttons -->\n		</div>\n		<!-- /wp:column -->\n		<!-- wp:column {\"width\":\"64%\"} -->\n		<div class=\"wp-block-column\" style=\"flex-basis:64%\">\n			<!-- wp:academia/faq {\"schema\":true,\"items\":[{\"q\":\"How do I book a place on a public course?\",\"a\":\"Choose your date on the course page and complete the checkout. You can pay by card, iDEAL, Bancontact, SEPA transfer or request an invoice for your employer. Confirmation and joining instructions arrive immediately by email.\"},{\"q\":\"Can my employer be invoiced directly?\",\"a\":\"Yes. Select “Pay by invoice” at checkout and enter your company details and PO number. We issue a VAT-compliant invoice with 30-day terms and handle EU reverse-charge automatically for valid VAT numbers.\"},{\"q\":\"What is your cancellation policy?\",\"a\":\"Free cancellation or transfer up to 14 days before the start date. Within 14 days you may send a colleague in your place at no cost. If we cancel a date, you receive a full refund or a free transfer.\"},{\"q\":\"Do I receive a certificate?\",\"a\":\"Every participant who completes a course receives a digital Academia certificate with a verification code, plus a LinkedIn-ready credential. Accredited programmes carry the awarding body’s certificate in addition.\"},{\"q\":\"Can a public course be delivered in-company instead?\",\"a\":\"Any course in the catalogue can be run onsite or privately online, customised to your systems and sector. From six participants this is usually cheaper than sending people individually.\"},{\"q\":\"What language is the training delivered in?\",\"a\":\"English, at every location and in every delivery mode. Materials, case studies and regulatory examples are localised to the market you work in, but the teaching language is English throughout — which is what makes one cohort work across several countries.\"}]} /-->\n		</div>\n		<!-- /wp:column -->\n	</div>\n	<!-- /wp:columns -->\n</div>\n<!-- /wp:group -->\n\n\n', 'Home', '', 'inherit', 'closed', 'closed', '', '2131-revision-v1', '', '', '2026-08-23 22:58:07', '2026-08-23 22:58:07', '', 2131, 'https://academiatraining.eu/?p=2167', 0, 'revision', '', 0),
(2168, 1, '2026-08-23 22:58:07', '2026-08-23 22:58:07', '<!-- wp:group {\"className\":\"wrap section\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group wrap section\">\n	<!-- wp:academia/breadcrumbs /-->\n	<!-- wp:paragraph {\"className\":\"is-style-academia-eyebrow\"} --><p class=\"is-style-academia-eyebrow\">Legal</p><!-- /wp:paragraph -->\n	<!-- wp:post-title {\"level\":1} /-->\n	<!-- wp:paragraph {\"fontSize\":\"x-small\",\"className\":\"muted\"} -->\n	[academia_legal_footer]\n	<!-- /wp:paragraph -->\n\n	\n\n	<!-- wp:group {\"style\":{\"spacing\":{\"margin\":{\"top\":\"36px\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"760px\"}} -->\n	<div class=\"wp-block-group\" style=\"margin-top:36px\">\n		<!-- wp:paragraph {\"placeholder\":\"Paste the reviewed legal text here.\"} --><p></p><!-- /wp:paragraph -->\n	</div>\n	<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n\n\n', 'Cookie Settings', '', 'inherit', 'closed', 'closed', '', '2147-revision-v1', '', '', '2026-08-23 22:58:07', '2026-08-23 22:58:07', '', 2147, 'https://academiatraining.eu/?p=2168', 0, 'revision', '', 0),
(2169, 1, '2026-08-23 22:58:07', '2026-08-23 22:58:07', '<!-- wp:group {\"className\":\"wrap section\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group wrap section\">\n	<!-- wp:academia/breadcrumbs /-->\n	<!-- wp:paragraph {\"className\":\"is-style-academia-eyebrow\"} --><p class=\"is-style-academia-eyebrow\">Legal</p><!-- /wp:paragraph -->\n	<!-- wp:post-title {\"level\":1} /-->\n	<!-- wp:paragraph {\"fontSize\":\"x-small\",\"className\":\"muted\"} -->\n	[academia_legal_footer]\n	<!-- /wp:paragraph -->\n\n	\n\n	<!-- wp:group {\"style\":{\"spacing\":{\"margin\":{\"top\":\"36px\"}}},\"layout\":{\"type\":\"constrained\",\"contentSize\":\"760px\"}} -->\n	<div class=\"wp-block-group\" style=\"margin-top:36px\">\n		<!-- wp:paragraph {\"placeholder\":\"Paste the reviewed legal text here.\"} --><p></p><!-- /wp:paragraph -->\n	</div>\n	<!-- /wp:group -->\n</div>\n<!-- /wp:group -->\n\n\n', 'Terms &amp; Conditions', '', 'inherit', 'closed', 'closed', '', '2145-revision-v1', '', '', '2026-08-23 22:58:07', '2026-08-23 22:58:07', '', 2145, 'https://academiatraining.eu/?p=2169', 0, 'revision', '', 0);
